using Crownfall.Battle; using Crownfall.Core; using Crownfall.StatusEffects; using Crownfall.Units; using UnityEngine;
namespace Crownfall.Skills { public sealed class SkillController:MonoBehaviour { Unit unit;BattleController battle;BattleClock clock;SkillDefinition skill;float cast,recovery;Unit target; public bool Busy=>cast>0||recovery>0; public void Initialize(Unit u,BattleController b,BattleClock c){unit=u;battle=b;clock=c;skill=u.Definition.skill;} public void Tick(){if(unit==null||unit.IsDead||clock==null)return;unit.Shields?.Tick(clock);unit.Statuses?.Tick(clock,battle.Damage);float dt=clock.DeltaTime;if(dt<=0)return;if(recovery>0){recovery=Mathf.Max(0,recovery-dt);return;}if(cast>0){if(!unit.CanCastSkill){Cancel();return;}cast-=dt;if(cast<=0)Resolve();return;}if(skill!=null&&unit.CanCastSkill&&unit.Energy.Current>=skill.energyCost){target=SkillTargetResolver.Resolve(unit,skill,battle);if(target!=null){cast=Mathf.Max(.001f,skill.castTime);unit.SetState(UnitState.Casting);}}} void Resolve(){if(target==null||target.IsDead||!unit.CanCastSkill){Cancel();return;}if(!unit.Energy.TrySpend(skill.energyCost)){Cancel();return;}var ctx=new SkillContext(unit,skill,battle);foreach(var e in skill.effects)if(e!=null)e.Execute(ctx,target);recovery=skill.recoveryTime;if(!unit.IsDead)unit.SetState(UnitState.Idle);target=null;} void Cancel(){cast=0;target=null;if(unit!=null&&!unit.IsDead)unit.SetState(UnitState.Idle);} } }
